package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen0Test {

    @Test
    public void testValueTrue() throws IOException {
        StringWriter sw = new StringWriter();
        JsonWriter writer = new JsonWriter(sw);

        writer.beginObject();
        writer.name("testKey");
        JsonWriter result = writer.value(true);
        writer.endObject();
        writer.flush();

        String expected = "{\"testKey\":true}";
        assertEquals(expected, sw.toString());
        assertSame(writer, result);
    }

    @Test
    public void testValueFalse() throws IOException {
        StringWriter sw = new StringWriter();
        JsonWriter writer = new JsonWriter(sw);

        writer.beginObject();
        writer.name("testKey");
        JsonWriter result = writer.value(false);
        writer.endObject();
        writer.flush();

        String expected = "{\"testKey\":false}";
        assertEquals(expected, sw.toString());
        assertSame(writer, result);
    }

    @Test
    public void testValueInArray() throws IOException {
        StringWriter sw = new StringWriter();
        JsonWriter writer = new JsonWriter(sw);

        writer.beginArray();
        writer.value(true);
        writer.value(false);
        writer.endArray();
        writer.flush();

        String expected = "[true,false]";
        assertEquals(expected, sw.toString());
    }

    @Test
    public void testValueThrowsIOException() throws IOException {
        // Create a custom writer that throws IOException on write
        class ThrowingWriter extends java.io.Writer {
            @Override
            public void write(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("Simulated IO error");
            }

            @Override
            public void flush() throws IOException {}

            @Override
            public void close() throws IOException {}
        }

        JsonWriter writer = new JsonWriter(new ThrowingWriter());
        writer.beginObject();
        writer.name("key");

        try {
            writer.value(true);
            org.junit.Assert.fail("Should have thrown IOException");
        } catch (IOException e) {
            assertEquals("Simulated IO error", e.getMessage());
        }
    }
}
